# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Scalar kernel - used for unaligned pointers or when numel % 4 != 0
__global__ void fused_post_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int64_t numel,
    int64_t HW,
    int64_t C,
    float scale,
    float inv_scale
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) return;

    int64_t c = (idx / HW) % C;
    float v = x[idx] + __ldg(&bias[c]);
    v = fminf(fmaxf(v, 0.0f), 1.0f);
    v = v * scale;
    v = fminf(fmaxf(v, 0.0f), 1.0f);
    v = v * inv_scale;
    out[idx] = v;
}

// Float4 vectorized kernel - 4 floats per thread via 128-bit loads/stores
__global__ void fused_post_ops_kernel_vec4(
    const float4* __restrict__ x4,
    const float* __restrict__ bias,
    float4* __restrict__ out4,
    int64_t npacks,
    int64_t HW,
    int64_t C,
    float scale,
    float inv_scale
) {
    int64_t pid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (pid >= npacks) return;

    int64_t base = pid * 4;
    float4 v = x4[pid];

    {
        int64_t c = ((base + 0) / HW) % C;
        float val = v.x + __ldg(&bias[c]);
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        val = val * scale;
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        v.x = val * inv_scale;
    }
    {
        int64_t c = ((base + 1) / HW) % C;
        float val = v.y + __ldg(&bias[c]);
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        val = val * scale;
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        v.y = val * inv_scale;
    }
    {
        int64_t c = ((base + 2) / HW) % C;
        float val = v.z + __ldg(&bias[c]);
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        val = val * scale;
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        v.z = val * inv_scale;
    }
    {
        int64_t c = ((base + 3) / HW) % C;
        float val = v.w + __ldg(&bias[c]);
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        val = val * scale;
        val = fminf(fmaxf(val, 0.0f), 1.0f);
        v.w = val * inv_scale;
    }

    out4[pid] = v;
}

torch::Tensor fused_post_ops_cuda(torch::Tensor x, torch::Tensor bias, double scaling_factor) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (NCHW)");

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t HW = H * W;
    int64_t numel = N * C * HW;

    auto out = torch::empty_like(x);

    float scale = (float)scaling_factor;
    float inv_scale = 1.0f / scale;

    const float* xptr = x.data_ptr<float>();
    float* outptr = out.data_ptr<float>();
    const float* biasptr = bias.data_ptr<float>();

    const int block = 256;

    bool use_vec4 = (reinterpret_cast<uintptr_t>(xptr) % 16 == 0) &&
                    (reinterpret_cast<uintptr_t>(outptr) % 16 == 0) &&
                    (numel % 4 == 0);

    if (use_vec4) {
        int64_t npacks = numel / 4;
        int64_t grid = (npacks + block - 1) / block;
        fused_post_ops_kernel_vec4<<<grid, block>>>(
            reinterpret_cast<const float4*>(xptr),
            biasptr,
            reinterpret_cast<float4*>(outptr),
            npacks,
            HW,
            C,
            scale,
            inv_scale
        );
    } else {
        int64_t grid = (numel + block - 1) / block;
        fused_post_ops_kernel<<<grid, block>>>(
            xptr,
            biasptr,
            outptr,
            numel,
            HW,
            C,
            scale,
            inv_scale
        );
    }

    return out;
}
